export interface TocEntry {
  level: 2 | 3;
  text: string;
  id: string;
}

export interface GuideLink {
  path: string;
  hierarchy: string[];
  slug: string;
  title: string;
  to: string;
}

export function slugify(text: string): string {
  return text
    .trim()
    .toLowerCase()
    .replace(/[^\p{L}\p{N}\s-]/gu, '') // drop punctuation, incl. ":"
    .replace(/\s+/g, '-')
    .replace(/-+/g, '-')
    .replace(/^-+|-+$/g, '');
}

const FRONTMATTER_RE = /^﻿?---\r?\n([\s\S]*?)\r?\n---[ \t]*\r?\n?/;

export function stripFrontmatter(source: string): string {
  return (source ?? '').replace(FRONTMATTER_RE, '');
}

export type DocStatus = 'draft' | 'active';

export interface DocFrontmatter {
  status?: DocStatus;
  reviewNote?: string;
}

// Parse the leading YAML frontmatter for the fields the docs UI surfaces (status, review note).
export function parseDocFrontmatter(source: string): DocFrontmatter {
  const body = (source ?? '').match(FRONTMATTER_RE)?.[1];
  if (!body) return {};

  const readField = (key: string): string | undefined => {
    const match = body.match(new RegExp(`^${key}:[ \\t]*(.+?)[ \\t]*$`, 'm'));
    return match?.[1].replace(/^["']|["']$/g, '').trim() || undefined;
  };

  const status = readField('status')?.toLowerCase();
  return {
    status: status === 'draft' || status === 'active' ? status : undefined,
    reviewNote: readField('reviewNote') ?? readField('review_note'),
  };
}

/** `start-shift` -> `Start Shift`; `subcontractor_canvasser` -> `Subcontractor Canvasser`. */
export function humanizeSlug(slug: string): string {
  return slug
    .split(/[-_]/)
    .filter(Boolean)
    .map((word) => word.charAt(0).toUpperCase() + word.slice(1))
    .join(' ');
}

/** In-app route for a guide doc path: `guides/admin/x.md` -> `/docs/guides/admin/x`. */
export function docPathToRoute(path: string): string {
  return `/docs/${path.replace(/\.md$/i, '')}`;
}

export function parseDocPath(path: string): GuideLink {
  const clean = path.replace(/\.md$/i, '');
  const segments = clean.split('/');
  const hierarchy = segments.length > 1 ? segments.slice(0, -1) : [];
  const slug = segments[segments.length - 1];
  return {
    path,
    hierarchy,
    slug,
    title: humanizeSlug(slug),
    to: docPathToRoute(path),
  };
}

export interface DocsHierarchy {
  title: string;
  contents: DocsNode[];
}

export type DocsNode = GuideLink | DocsHierarchy;

export function isDocsHierarchy(node: DocsNode): node is DocsHierarchy {
  return 'contents' in node;
}

function getHierarchy(path: string[], nodes: DocsNode[]): DocsHierarchy {
  const title = humanizeSlug(path[0]);
  const found = nodes.find((node): node is DocsHierarchy => isDocsHierarchy(node) && node.title === title);
  const folder = found ?? { title, contents: [] };
  if (!found) nodes.push(folder);

  return path.length === 1 ? folder : getHierarchy(path.slice(1), folder.contents);
}

function compareNodes(a: DocsNode, b: DocsNode): number {
  const rank = (node: DocsNode) => (!isDocsHierarchy(node) && node.slug === 'getting-started' ? 0 : 1);
  return rank(a) - rank(b) || a.title.localeCompare(b.title);
}

function sortTree(nodes: DocsNode[]): void {
  nodes.sort(compareNodes);
  for (const node of nodes) {
    if (isDocsHierarchy(node)) sortTree(node.contents);
  }
}

export function groupGuides(paths: string[]): DocsNode[] {
  const tree: DocsNode[] = [];

  for (const path of paths) {
    const link = parseDocPath(path);
    const container = link.hierarchy.length ? getHierarchy(link.hierarchy, tree).contents : tree;
    container.push(link);
  }

  sortTree(tree);
  return tree;
}

export function extractDocTitle(source: string): string | null {
  const match = stripFrontmatter(source).match(/^#\s+(.+?)\s*$/m);
  return match ? match[1].trim() : null;
}
